import subprocess, sys, os, shutil, json
BASE="/tmp/work/latex08/sandbox"
def render(md, book_extra="", args=None, files=None, show="content", single=False):
    if os.path.exists(BASE): shutil.rmtree(BASE)
    os.makedirs(BASE)
    open(BASE+"/ch1.md","w").write(md)
    if files:
        for k,v in files.items():
            p=os.path.join(BASE,k)
            os.makedirs(os.path.dirname(p),exist_ok=True)
            if isinstance(v,bytes): open(p,"wb").write(v)
            else: open(p,"w").write(v)
    if single:
        cmd=["/tmp/ref/crowbook","-q","-s",BASE+"/ch1.md","-t","tex","-o",BASE+"/out.tex"]
    else:
        open(BASE+"/book.md","w").write("author: Me\ntitle: Test Book\nlang: en\n"+book_extra+"\n+ ch1.md\n")
        cmd=["/tmp/ref/crowbook","-q",BASE+"/book.md","-t","tex","-o",BASE+"/out.tex"]
    if args: cmd+=args
    r=subprocess.run(cmd,capture_output=True,text=True)
    out=""
    if os.path.exists(BASE+"/out.tex"):
        out=open(BASE+"/out.tex").read()
    return r, out
def content(out):
    i=out.find("\\begin{document}")
    return out[i:] if i>=0 else out
if __name__=="__main__":
    md=sys.stdin.read()
    extra=sys.argv[1] if len(sys.argv)>1 else ""
    r,out=render(md, extra)
    if r.returncode!=0 or r.stderr: sys.stderr.write("RC=%d STDERR=%r\n"%(r.returncode,r.stderr))
    sys.stdout.write(content(out))
EOF
